package org.eclipse.rdf4j.query.algebra.evaluation.rdfparser;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Set;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.QueryRoot;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.evaluation.function.TupleFunctionRegistry;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.eclipse.rdf4j.query.impl.MapBindingSet;
import org.eclipse.rdf4j.query.parser.sparql.SPARQLParser;
import org.junit.jupiter.api.Test;

class RdfParserQuerySupportTest {

	private static final String PREFIX = "PREFIX parse: <http://rdf4j.org/function/parse#> ";

	private static TupleExpr parse(String query) {
		return new SPARQLParser().parseQuery(PREFIX + query, null).getTupleExpr();
	}

	@Test
	void builtinsArePresentWithoutInitializingAnySail() {
		var registry = new TupleFunctionRegistry();
		for (var iri : Set.of(RdfParseVocabulary.TRIPLES, RdfParseVocabulary.QUADS,
				RdfParseVocabulary.TRIPLE_TERMS, RdfParseVocabulary.TURTLE)) {
			assertInstanceOf(RdfParseTupleFunction.class, registry.get(iri.stringValue()).orElseThrow());
		}
	}

	@Test
	void ordinaryQueriesRetainIdentityAndUnsubstitutedBindings() {
		TupleExpr original = parse("SELECT * WHERE { ?s ?p ?o }");
		String before = original.toString();
		MapBindingSet bindings = new MapBindingSet();
		bindings.addBinding("s", SimpleValueFactory.getInstance().createIRI("urn:s"));
		assertSame(original, RdfParserQuerySupport.rewrite(original, bindings));
		assertSame(original, RdfParserQuerySupport.rewriteOwned(original, bindings));
		assertEquals(before, original.toString());
	}

	@Test
	void rewrittenRootsAreIndependentAndNormalizationIsIdempotentAcrossClones() {
		TupleExpr original = parse("SELECT * WHERE { ?doc parse:turtle (?s ?p ?o) }");
		String before = original.toString();
		MapBindingSet bindings = new MapBindingSet();
		bindings.addBinding("doc", SimpleValueFactory.getInstance().createLiteral("<urn:s> <urn:p> <urn:o> ."));
		TupleExpr rewritten = RdfParserQuerySupport.rewrite(original, bindings);
		assertNotSame(original, rewritten);
		assertInstanceOf(QueryRoot.class, rewritten);
		assertNull(rewritten.getParentNode());
		assertFalse(((QueryRoot) rewritten).getArg() instanceof QueryRoot);
		assertEquals(before, original.toString());
		assertSame(rewritten, RdfParserQuerySupport.rewrite(rewritten, bindings));
		assertSame(rewritten, RdfParserQuerySupport.rewriteOwned(rewritten, bindings));
		TupleExpr cloned = rewritten.clone();
		assertSame(cloned, RdfParserQuerySupport.rewriteOwned(cloned, bindings));
		assertTrue(RdfParserQuerySupport.isParserQuery(cloned));
	}

	@Test
	void remoteServiceBodiesRemainOwnedByTheReceivingEngine() {
		TupleExpr query = parse("SELECT * WHERE { SERVICE <urn:remote> { ?doc parse:turtle (?s ?p ?o) } }");
		assertFalse(RdfParserQuerySupport.isParserQuery(query));
		assertSame(query, RdfParserQuerySupport.rewrite(query, EmptyBindingSet.getInstance()));
	}

	@Test
	void unboundVariableServicesRemainOrdinaryAlgebra() {
		TupleExpr query = parse("SELECT * WHERE { SERVICE ?endpoint { ?s ?p ?o } }");
		assertFalse(RdfParserQuerySupport.isParserQuery(query));
		assertSame(query, RdfParserQuerySupport.rewrite(query, EmptyBindingSet.getInstance()));
	}
}
